import type { Mock } from "vitest";
import type { H3Config, H3Event, NodeHandler, HTTPError } from "../src/index.ts";
import { tracingPlugin } from "../src/tracing.ts";
import { Server as NodeServer } from "node:http";
import { getRandomPort } from "get-port-please";
import { beforeEach, afterEach, vi, it, describe, expect, beforeAll, afterAll } from "vitest";
import { H3 } from "../src/index.ts";
import { toNodeHandler } from "../src/_entries/node.ts";

// Matrix
export function describeMatrix(
  title: string,
  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
  opts?: TestOptions,
): void {
  const run = (ctx: TestContext) => {
    const utils: TestUtils = {
      expect,
      describe,
      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
        only: interceptFnWithSuffix(it.only, ctx.target),
        todo: interceptFnWithSuffix(it.todo, ctx.target),
        skip: interceptFnWithSuffix(it.skip, ctx.target),
        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
      }),
    };
    fn(ctx, utils);
  };
  describe(title, () => {
    describe("web", () => {
      run(setupWebTest(opts));
    });
    describe("node", () => {
      run(setupNodeTest(opts));
    });
  });
}

// Web
function setupWebTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("web", opts);
  beforeEach(() => {
    ctx.fetch = (input, init) => {
      const headers = new Headers(init?.headers);
      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
        headers.set("Host", "localhost");
      }
      return Promise.resolve(
        ctx.app.request(input, {
          ...init,
          headers,
        }),
      );
    };
  });
  return ctx;
}

// Node.js
function setupNodeTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("node", opts);

  let server: NodeServer;
  let handler: NodeHandler;

  beforeAll(async () => {
    server = new NodeServer((req, res) => {
      handler!(req, res);
    });
    const port = await getRandomPort();
    await new Promise<void>((resolve) => server.listen(port, resolve));
    ctx.url = `http://localhost:${port}`;
    ctx.fetch = (input, init = {}) => {
      const url = new URL(input, ctx.url);
      const headers = new Headers(init.headers);
      // Emulate a reverse proxy
      if (!headers.has("host")) {
        headers.set("Host", url.host);
      }
      if (!headers.has("x-forwarded-host")) {
        headers.set("X-Forwarded-Host", url.host);
      }
      if (url.protocol === "https:" && !headers.has("x-forwarded-proto")) {
        headers.set("X-Forwarded-Proto", "https");
      }
      return fetch(`${ctx.url}${url.pathname}${url.search}`, {
        redirect: "manual",
        // @ts-expect-error undici/node specific
        duplex: "half",
        ...init,
        headers,
      });
    };
  });

  afterAll(async () => {
    server.closeAllConnections();
    await new Promise<void>((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve())),
    );
    server = undefined!;
  });

  beforeEach(async () => {
    handler = toNodeHandler(ctx.app);
  });

  afterEach(() => {
    handler = undefined!;
  });

  return ctx;
}

// Base
function setupBaseTest(target: TestContext["target"], opts: TestOptions = {}): TestContext {
  const ctx: TestContext = { target } as TestContext;

  beforeEach(async () => {
    ctx.hooks = {
      onRequest: vi.fn(),
      onError: vi.fn(),
      onResponse: vi.fn(),
    };

    ctx.errors = [];
    ctx.hooks.onError.mockImplementation((error, _event: H3Event) => {
      if (opts.debug) {
        console.error(error);
      }
      ctx.errors.push(error);
    });

    ctx.app = new H3({
      debug: true,
      onError: ctx.hooks.onError,
      onRequest: ctx.hooks.onRequest,
      onResponse: ctx.hooks.onResponse,
      plugins: [opts.tracing ? tracingPlugin() : undefined].filter((p) => !!p),
    });
  });

  afterEach(async () => {
    const errors = ctx.errors;

    ctx.app = undefined!;
    ctx.hooks = undefined!;
    ctx.errors = undefined!;

    vi.resetAllMocks();
    if (!opts.allowUnhandledErrors) {
      const unhandledErrors = errors.filter((error) => error.unhandled);
      if (unhandledErrors.length > 0) {
        throw mergeErrors(errors);
      }
    }
  });

  return ctx;
}

// --- types ---

export interface TestOptions {
  allowUnhandledErrors?: boolean;
  startServer?: boolean;
  debug?: boolean;
  tracing?: boolean;
}

export interface TestContext {
  errors: HTTPError[];
  hooks: {
    onRequest: Mock<Exclude<H3Config["onRequest"], undefined>>;
    onError: Mock<Exclude<H3Config["onError"], undefined>>;
    onResponse: Mock<Exclude<H3Config["onResponse"], undefined>>;
  };

  target: "web" | "node";
  app: H3;
  url?: string;
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
}

export interface TestUtils {
  it: typeof it;
  describe: typeof describe;
  expect: typeof expect;
}

// --- utils ---

function mergeErrors(err: Error | Error[]) {
  if (Array.isArray(err)) {
    if (err.length === 1) {
      return mergeErrors(err[0]);
    }
    return new Error(
      "[tests] H3 global errors: \n" + err.map((error) => " - " + (error.stack || "")).join("\n"),

13:      it(`omits the body for a missing HEAD route ${hook}`, async () => {
15:        const res = await t.fetch("/missing", { method: "HEAD" });
17:        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
  });

  it("event.req.headers uses request header names", () => {
    type HeaderName = Parameters<H3Event["req"]["headers"]["delete"]>[0];
    expectTypeOf<Extract<HeaderName, "Authorization">>().toEqualTypeOf<"Authorization">();
    expectTypeOf<Extract<HeaderName, "X-Powered-By">>().toBeNever();
  });

  type ReqOf<H> = H extends (event: H3Event<infer R>) => any ? R : never;

  describe("eventHandler", () => {
    it("return type (inferred)", () => {
      const handler = defineHandler(() => {
        return {
          foo: "bar",
        };
      });
      const response = handler({} as H3Event);
      expectTypeOf(response).toEqualTypeOf<{ foo: string }>();
    });
  });

