import { build } from "esbuild";
import { fileURLToPath } from "node:url";
import zlib from "node:zlib";

const entries = {
  H3: `import { H3 } from "../../src/index.ts"; const app = new H3();`,
  H3Core: `import { H3Core } from "../../src/index.ts"; const app = new H3Core();`,
  defineHandler: `import { defineHandler } from "../../src/index.ts"; const h = defineHandler(() => "x");`,
};

for (const [name, code] of Object.entries(entries)) {
  const res = await build({
    bundle: true,
    metafile: true,
    write: false,
    minify: true,
    format: "esm",
    platform: "node",
    outfile: "index.mjs",
    treeShaking: true,
    conditions: ["browser"],
    logOverride: { "ignored-bare-import": "silent" },
    stdin: {
      contents: code,
      resolveDir: fileURLToPath(new URL(".", import.meta.url)),
      sourcefile: "index.mjs",
      loader: "js",
    },
